const AA_EXTRACT = // Runs in the page. Finds every fillable control in the application form, works out a
// human-readable label for it, tags it with data-aa-key, and returns a field list.
(rootSelector) => {
  const clean = (s) => (s || "").replace(/[✱*]/g, " ").replace(/\s+/g, " ").trim();
  const GENERIC = /^(attach|upload|upload file|choose file|browse|drop files? here|enter manually)?$/i;
  const visible = (el) => {
    if (!el) return false;
    if (el.type === "file") return true; // file inputs are usually hidden behind a button
    const r = el.getBoundingClientRect();
    const st = getComputedStyle(el);
    return (r.width > 0 || r.height > 0) && st.visibility !== "hidden" && st.display !== "none";
  };
  const textOf = (el) => (el ? clean(el.innerText || el.textContent) : "");
  // Visible label text, skipping nested controls (a <select>'s options) and hidden helper text
  // ("Analyzing resume...", "No location found").
  const SKIP = "select, option, input, textarea, [role=listbox], [role=option], button, script, style, svg";
  const labelText = (node) => {
    let out = "";
    for (const c of node.childNodes) {
      if (c.nodeType === Node.TEXT_NODE) out += " " + c.textContent;
      else if (c.nodeType === Node.ELEMENT_NODE && !c.matches(SKIP)) {
        const st = getComputedStyle(c);
        if (st.display === "none" || st.visibility === "hidden") continue;
        out += " " + labelText(c);
      }
    }
    return clean(out);
  };

  const root =
    (rootSelector && document.querySelector(rootSelector)) ||
    [...document.querySelectorAll("form")].find((f) => f.querySelector("input[type=file], textarea, input[type=email]")) ||
    document.body;

  const labelFor = (el) => {
    if (el.labels && el.labels.length) {
      const t = clean([...el.labels].map(labelText).join(" "));
      if (t && !GENERIC.test(t)) return t;
    }
    const lb = el.getAttribute("aria-labelledby");
    if (lb) {
      const t = clean(lb.split(/\s+/).map((id) => textOf(document.getElementById(id))).join(" "));
      if (t) return t;
    }
    if (el.getAttribute("aria-label")) return clean(el.getAttribute("aria-label"));
    const wrap = el.closest("label");
    if (wrap && labelText(wrap) && !GENERIC.test(labelText(wrap))) return labelText(wrap);
    // Walk up a few levels looking for a label-like element that doesn't contain the control.
    let node = el.parentElement;
    for (let depth = 0; node && node !== root && depth < 5; depth++, node = node.parentElement) {
      const cand = node.querySelector(
        ":scope > label, :scope > legend, :scope > [class*='label' i], :scope > [class*='question' i], :scope > [class*='title' i]"
      );
      if (cand && !cand.contains(el) && labelText(cand) && !GENERIC.test(labelText(cand))) return labelText(cand);
    }
    const fs = el.closest("fieldset");
    if (fs && fs.querySelector("legend")) return textOf(fs.querySelector("legend"));
    return clean(el.getAttribute("placeholder") || el.name || el.id);
  };

  const groupLabel = (inputs) => {
    const first = inputs[0];
    const fs = first.closest("fieldset");
    if (fs && fs.querySelector("legend")) return textOf(fs.querySelector("legend"));
    const rg = first.closest("[role=radiogroup], [role=group]");
    if (rg) {
      const lb = rg.getAttribute("aria-labelledby");
      if (lb && document.getElementById(lb)) return textOf(document.getElementById(lb));
      if (rg.getAttribute("aria-label")) return clean(rg.getAttribute("aria-label"));
    }
    // Climb until the ancestor holds the whole group, then look for its heading.
    let node = first.parentElement;
    while (node && node !== root && !inputs.every((i) => node.contains(i))) node = node.parentElement;
    for (let depth = 0; node && node !== root && depth < 4; depth++, node = node.parentElement) {
      const cand = node.querySelector(
        ":scope > label, :scope > legend, :scope > [class*='label' i], :scope > [class*='question' i], :scope > [class*='title' i], :scope > div > label:not(:has(input))"
      );
      if (cand && !inputs.some((i) => cand.contains(i)) && textOf(cand)) return textOf(cand);
    }
    return clean(first.name);
  };

  // The question heading above a group of options (not one of the options' own labels).
  const questionHeading = (inputs, optionTexts) => {
    let node = inputs[0].parentElement;
    while (node && node !== root && !inputs.every((i) => node.contains(i))) node = node.parentElement;
    for (let depth = 0; node && node !== root && depth < 4; depth++, node = node.parentElement) {
      const cands = node.querySelectorAll(":scope > label, :scope > legend, :scope > [class*='heading' i], :scope > [class*='label' i], :scope > [class*='question' i]");
      for (const cand of cands) {
        const text = labelText(cand);
        if (!text || inputs.some((i) => cand.contains(i)) || optionTexts.includes(text)) continue;
        const raw = cand.textContent || "";
        return { text, required: /required/i.test(cand.className || "") || /[*✱]\s*$/.test(raw.trim()) };
      }
    }
    return null;
  };

  const optionLabel = (input) => {
    if (input.labels && input.labels.length) return labelText(input.labels[0]);
    const wrap = input.closest("label");
    if (wrap) return labelText(wrap);
    const sib = input.nextElementSibling;
    if (sib && textOf(sib)) return textOf(sib);
    return clean(input.getAttribute("aria-label") || input.value);
  };

  // Some ATSs (Ashby) mark required questions only with a CSS class on the label.
  const labelMarkedRequired = (el) => {
    const lab = (el.labels && el.labels[0]) || el.closest("[data-field-path], fieldset, li")?.querySelector("label, legend");
    return !!(lab && /required/i.test(lab.className || ""));
  };
  const isRequired = (el, label) =>
    !!(el.required || el.getAttribute("aria-required") === "true" || /\*\s*$|\(required\)/i.test(label || "") ||
       labelMarkedRequired(el));

  const fields = [];
  let n = 0;
  const nextKey = () => `f${n++}`;
  const seenGroups = new Set();

  const controls = root.querySelectorAll("input, textarea, select, [role=combobox]");
  for (const el of controls) {
    if (el.closest("[data-aa-skip]")) continue;
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute("type") || "").toLowerCase();
    if (tag === "input" && ["hidden", "submit", "button", "reset", "image", "search"].includes(type)) continue;
    if (el.disabled || el.readOnly && type !== "file") continue;
    if (!visible(el)) continue;
    if (el.getAttribute("data-aa-key")) continue;
    // Hidden mirror inputs that some React selects add for native validation.
    if (type !== "file" && (el.getAttribute("aria-hidden") === "true" || el.tabIndex === -1)) continue;
    // react-select style comboboxes: the input carries role=combobox; skip the wrapper duplicates.
    if (tag !== "input" && tag !== "select" && tag !== "textarea" && el.querySelector("input")) continue;

    if (type === "radio" || type === "checkbox") {
      const name = el.name;
      let group = name
        ? [...root.querySelectorAll(`input[type=${type}][name="${CSS.escape(name)}"]`)]
        : [el];
      // Some ATSs (Ashby) give each checkbox of one question its own name; the question is the
      // field container they share, so group by that.
      const box = type === "checkbox" ? el.closest("[data-field-path], fieldset") : null;
      if (box) {
        const inBox = [...box.querySelectorAll("input[type=checkbox]")].filter(visible);
        if (inBox.length > group.length) group = inBox;
      }
      const gid = `${type}:${box && group.length > 1 ? "box" + n : name || n}`;
      if (group.some((g) => g.getAttribute("data-aa-key")) || seenGroups.has(gid)) continue;
      seenGroups.add(gid);
      const key = nextKey();
      const options = group.map(optionLabel);
      group.forEach((g, i) => { g.setAttribute("data-aa-key", key); g.setAttribute("data-aa-opt", options[i]); });
      const heading = questionHeading(group, options);
      let label = groupLabel(group);
      if (group.length === 1 && type === "checkbox") {
        // A lone checkbox: its own text ("I understand") plus the question it answers.
        label = heading && heading.text !== options[0] ? `${heading.text} — ${options[0]}` : options[0];
      } else if (heading && (!label || label === clean(el.name))) {
        label = heading.text;
      }
      fields.push({
        key, type: type === "radio" ? "radio" : group.length > 1 ? "checkbox_group" : "checkbox",
        label, options: group.length > 1 || type === "radio" ? options : [],
        required: group.some((g) => g.required) || /\*\s*$|\(required\)/i.test(label) ||
          !!el.closest("[aria-required=true]") || !!(heading && heading.required),
      });
      continue;
    }

    const key = nextKey();
    el.setAttribute("data-aa-key", key);
    const label = labelFor(el);
    let ftype = tag === "textarea" ? "textarea" : tag === "select" ? "select" : type || "text";
    if (el.getAttribute("role") === "combobox" && tag === "input") ftype = "combobox";
    const field = { key, type: ftype, label, required: isRequired(el, label), options: [] };
    if (tag === "select") {
      field.multiple = el.multiple;
      field.options = [...el.options]
        .map((o) => clean(o.text))
        .filter((t) => t && !/^(select|choose|please select|--)/i.test(t));
    }
    if (type === "file") field.accept = el.getAttribute("accept") || "";
    field.hint = clean(`${el.id || ""} ${el.name || ""} ${el.getAttribute("autocomplete") || ""}`);
    if (el.maxLength > 0) field.max_length = el.maxLength;
    const describedBy = el.getAttribute("aria-describedby");
    if (describedBy) {
      field.description = clean(describedBy.split(/\s+/).map((id) => textOf(document.getElementById(id))).join(" "));
    }
    fields.push(field);
  }
  // Yes/No style questions rendered as toggle buttons instead of inputs.
  const buttonGroups = new Map();
  root.querySelectorAll("button[aria-pressed]").forEach((b) => {
    const c = b.parentElement;
    if (!buttonGroups.has(c)) buttonGroups.set(c, []);
    buttonGroups.get(c).push(b);
  });
  for (const [container, buttons] of buttonGroups) {
    if (buttons.length < 2 || container.getAttribute("data-aa-key")) continue;
    const key = nextKey();
    const options = buttons.map((b) => clean(b.innerText));
    container.setAttribute("data-aa-key", key);
    buttons.forEach((b, i) => { b.setAttribute("data-aa-key", key); b.setAttribute("data-aa-opt", options[i]); });
    let label = "", required = false;
    let node = container;
    for (let depth = 0; node && node !== root && depth < 4 && !label; depth++, node = node.parentElement) {
      const lab = node.querySelector(":scope > label, :scope > legend, :scope > [class*='label' i]");
      if (lab && !buttons.some((b) => lab.contains(b))) {
        label = labelText(lab);
        required = /required/i.test(lab.className || "") || /\*\s*$/.test(lab.textContent || "");
      }
    }
    fields.push({ key, type: "radio", widget: "buttons", label, options, required });
  }
  return fields;
};

const AA_STATE = (keys) => {
  const out = {};
  for (const key of keys) {
    const els = [...document.querySelectorAll(`[data-aa-key="${key}"]`)];
    if (!els.length) { out[key] = null; continue; }
    const inputs = els.filter((e) => e.tagName === "INPUT" && (e.type === "checkbox" || e.type === "radio"));
    if (inputs.length) { out[key] = inputs.some((e) => e.checked); continue; }
    const buttons = els.filter((e) => e.tagName === "BUTTON");
    if (buttons.length) { out[key] = buttons.some((b) => b.getAttribute("aria-pressed") === "true"); continue; }
    const el = els[0];
    if (el.tagName === "SELECT") {
      const opt = el.options[el.selectedIndex];
      out[key] = !!(el.value && opt && !/^(select|choose|please select|--)/i.test(opt.text.trim()));
      continue;
    }
    if (el.type === "file") { out[key] = !!(el.files && el.files.length); continue; }
    if (el.getAttribute("role") === "combobox") {
      if (el.value && el.value.trim()) { out[key] = true; continue; }
      // react-select keeps the choice in a sibling element, not in the input.
      let n = el.parentElement, found = false;
      for (let d = 0; n && d < 4 && !found; d++, n = n.parentElement) {
        const v = n.querySelector("[class*='single-value' i], [class*='singleValue' i], [class*='multi-value' i]");
        if (v && v.innerText.trim()) found = true;
      }
      out[key] = found;
      continue;
    }
    out[key] = !!(el.value && el.value.trim());
  }
  return out;
};
